    --shadow-lg: 0 16px 40px -12px rgba(0, 0, 0, 0.6);
  }
}

:root[data-theme="dark"] {
  --bg: #0b0e14;
  --bg-elevated: #12161f;
  --bg-sunken: #0d1017;
  --border: #21262f;
  --border-strong: #2d333d;
  --text: #e6e8eb;
  --text-secondary: #9aa4b2;
  --text-muted: #616b7a;
  --accent: #818cf8;
  --accent-soft: #1e1b3a;
  --ok: #34d399;
  --ok-soft: #06281f;
  --warn: #fbbf24;
  --warn-soft: #2b1f06;
  --bad: #f87171;
  --bad-soft: #2a1414;
  --info: #38bdf8;
  --info-soft: #07222e;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 1px 3px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 16px 40px -12px rgba(0, 0, 0, 0.6);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 15px; }

body {
  font-family: var(--sans);
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }
code, pre, .mono { font-family: var(--mono); font-size: 0.86em; }

/* --- layout --- */

.app { display: grid; grid-template-columns: 232px 1fr; min-height: 100vh; }

.sidebar {
  border-right: 1px solid var(--border);
  background: var(--bg-elevated);
  padding: 20px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 8px 18px;
}
.brand .logo {
  width: 30px; height: 30px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), var(--info));
  display: grid; place-items: center;
  color: #fff; font-weight: 800; font-size: 14px;
  letter-spacing: -0.5px;
}
.brand .name { font-weight: 700; letter-spacing: -0.2px; }
.brand .sub { font-size: 11px; color: var(--text-muted); }

.nav-link {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  transition: background 0.12s, color 0.12s;
}
.nav-link:hover { background: var(--bg-sunken); color: var(--text); }
.nav-link.active { background: var(--accent-soft); color: var(--accent); }
.nav-link .ico { width: 16px; height: 16px; opacity: 0.9; flex: none; }

.sidebar .spacer { flex: 1; }
.sidebar-foot { font-size: 11px; color: var(--text-muted); padding: 8px; }
.theme-toggle {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 10px; border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 13px;
}
.theme-toggle:hover { background: var(--bg-sunken); }

.main { padding: 28px 34px 60px; max-width: 1180px; width: 100%; }

.page-head { margin-bottom: 22px; }
.page-head h1 { font-size: 22px; font-weight: 700; letter-spacing: -0.4px; }
.page-head p { color: var(--text-secondary); font-size: 14px; margin-top: 3px; }

/* --- primitives --- */

.card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.card-pad { padding: 18px 20px; }
.card-head {
  padding: 14px 20px;
  border-bottom: 1px solid var(--border);
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.grid { display: grid; gap: 16px; }
.grid.cols-2 { grid-template-columns: 1fr 1fr; }
.grid.cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid.cols-4 { grid-template-columns: repeat(4, 1fr); }
@media (max-width: 900px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { position: static; height: auto; flex-direction: row; flex-wrap: wrap; }
  .grid.cols-2, .grid.cols-3, .grid.cols-4 { grid-template-columns: 1fr; }
}

.stat { padding: 16px 18px; }
.stat .label { font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.stat .value { font-size: 26px; font-weight: 700; letter-spacing: -0.5px; margin-top: 4px; }
.stat .value.mono { font-size: 20px; }
.stat .foot { font-size: 12px; color: var(--text-secondary); margin-top: 3px; }

.badge {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 8px; border-radius: 999px;
  font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em;
  border: 1px solid transparent;
}
.badge .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.badge.SUCCESS, .badge.pass, .badge.up, .badge.COMPLETE { color: var(--ok); background: var(--ok-soft); }
.badge.REGRESSION, .badge.ERROR, .badge.fail, .badge.down, .badge.FAILED { color: var(--bad); background: var(--bad-soft); }
.badge.PARTIAL_SUCCESS, .badge.NEEDS_REVIEW, .badge.uncertain, .badge.PARTIAL { color: var(--warn); background: var(--warn-soft); }
.badge.IN_PROGRESS, .badge.linked, .badge.NOT_STARTED { color: var(--info); background: var(--info-soft); }
.badge.missing { color: var(--text-muted); background: var(--bg-sunken); }

.pill { font-family: var(--mono); font-size: 11.5px; background: var(--bg-sunken); border: 1px solid var(--border); padding: 1px 6px; border-radius: 5px; color: var(--text-secondary); }

.muted { color: var(--text-muted); }
.secondary { color: var(--text-secondary); }
.plus { color: var(--ok); }
.minus { color: var(--bad); }

/* --- version list / timeline --- */

.vrow {
  display: grid;
  grid-template-columns: 44px 110px 1fr auto;
  gap: 14px;
  align-items: center;
  padding: 12px 20px;
  border-bottom: 1px solid var(--border);
  transition: background 0.1s;
}
.vrow:last-child { border-bottom: none; }
.vrow:hover { background: var(--bg-sunken); }
.vrow .vid { font-weight: 700; font-size: 14px; }
.vrow .vintent { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; }
.vrow .vmeta { font-size: 12px; color: var(--text-muted); display: flex; gap: 10px; }

.timeline { position: relative; padding-left: 30px; }
.timeline::before { content: ""; position: absolute; left: 9px; top: 8px; bottom: 8px; width: 2px; background: var(--border); }
.tl-item { position: relative; padding: 14px 0; border-bottom: 1px solid var(--border); }
.tl-item:last-child { border-bottom: none; }
.tl-item::before {
  content: ""; position: absolute; left: -25px; top: 20px;
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--bg); border: 2.5px solid var(--border-strong);
}
.tl-item.SUCCESS::before { border-color: var(--ok); }
.tl-item.REGRESSION::before, .tl-item.ERROR::before { border-color: var(--bad); }
.tl-item.PARTIAL_SUCCESS::before, .tl-item.NEEDS_REVIEW::before { border-color: var(--warn); }
.tl-head { display: flex; align-items: center; gap: 10px; }
.tl-head .vid { font-weight: 700; }
.tl-body { margin-top: 4px; font-size: 14px; }
.tl-metrics { margin-top: 6px; display: flex; gap: 8px; flex-wrap: wrap; }

/* --- development trace --- */

.trace { display: flex; flex-direction: column; gap: 0; }
.trace-node {
  position: relative;
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 16px;
  padding: 12px 0 12px 22px;
}
.trace-node::before {
  content: ""; position: absolute; left: 5px; top: 18px;
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--accent); box-shadow: 0 0 0 4px var(--accent-soft);
}
.trace-node:not(:last-child)::after {
  content: ""; position: absolute; left: 9px; top: 28px; bottom: -12px; width: 2px;
  background: var(--border-strong);
}
.trace-node .t-label { font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; padding-top: 2px; }
.trace-node .t-value { font-size: 14px; font-weight: 500; word-break: break-word; }
.trace-node .t-detail { font-size: 12.5px; color: var(--text-secondary); margin-top: 2px; }
.trace-node[data-source="entire"]::before { background: var(--info); box-shadow: 0 0 0 4px var(--info-soft); }
.trace-node[data-source="status"]::before { background: var(--warn); box-shadow: 0 0 0 4px var(--warn-soft); }

/* --- diff viewer --- */

.diff {
  font-family: var(--mono);
  font-size: 12.5px;
  line-height: 1.55;
  background: var(--bg-sunken);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow-x: auto;
  max-height: 560px;
  overflow-y: auto;
}
.diff .l { display: block; padding: 0 12px; white-space: pre; }
.diff .l.add { background: var(--ok-soft); color: var(--ok); }
.diff .l.del { background: var(--bad-soft); color: var(--bad); }
.diff .l.hunk { color: var(--info); background: var(--info-soft); }
.diff .l.meta { color: var(--text-muted); }

/* --- misc --- */

.kv { display: grid; grid-template-columns: 130px 1fr; gap: 6px 16px; font-size: 14px; }
.kv dt { color: var(--text-muted); }
.kv dd { word-break: break-word; }

.files-list { font-family: var(--mono); font-size: 12.5px; }
.files-list .f { display: flex; gap: 10px; padding: 4px 0; align-items: baseline; }
.files-list .mark { width: 14px; font-weight: 700; }
.files-list .mark.A { color: var(--ok); }
.files-list .mark.M { color: var(--warn); }
.files-list .mark.D { color: var(--bad); }
.files-list .mark.R, .files-list .mark.C { color: var(--info); }

.search-box {
  width: 100%;
  padding: 11px 14px;
  border-radius: var(--radius);
  border: 1px solid var(--border-strong);
  background: var(--bg-elevated);
  color: var(--text);
  font-size: 15px;
}
.search-box:focus { outline: 2px solid var(--accent); outline-offset: -1px; border-color: transparent; }

select.search-box { cursor: pointer; }

.empty { text-align: center; padding: 48px 20px; color: var(--text-muted); }
.empty .big { font-size: 15px; color: var(--text-secondary); margin-bottom: 4px; }

.toast {
  position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%);
  background: var(--bad); color: #fff; padding: 10px 18px; border-radius: 8px;
  font-size: 13px; box-shadow: var(--shadow-lg); z-index: 50;
}

.link { color: var(--accent); font-weight: 500; }
.link:hover { text-decoration: underline; }

.metric-delta { display: inline-flex; align-items: baseline; gap: 6px; font-family: var(--mono); font-size: 13px; }
.metric-delta .arrow { color: var(--text-muted); }

.spin { display: inline-block; width: 16px; height: 16px; border: 2px solid var(--border-strong); border-top-color: var(--accent); border-radius: 50%; animation: spin 0.7s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

hr.sep { border: none; border-top: 1px solid var(--border); margin: 22px 0; }

